begin;
do $$
declare a text='MYAOW-MEDIA-TEST-A'; b text='MYAOW-MEDIA-TEST-B'; c text='MYAOW-MEDIA-TEST-C';
 ta text=repeat('a',64); tb text=repeat('b',64); tc text=repeat('c',64);
 mid uuid=gen_random_uuid(); gid uuid=gen_random_uuid(); gm uuid=gen_random_uuid(); request jsonb; result jsonb;
begin
 insert into myaow_private.profiles(id,username,display_name,identity_key_hex) values(a,'media_test_a','A',repeat('1',64)),(b,'media_test_b','B',repeat('2',64)),(c,'media_test_c','C',repeat('3',64));
 insert into myaow_private.sessions(token_hash,owner,expires_at) values(encode(extensions.digest(ta,'sha256'),'hex'),a,now()+interval '1 hour'),(encode(extensions.digest(tb,'sha256'),'hex'),b,now()+interval '1 hour'),(encode(extensions.digest(tc,'sha256'),'hex'),c,now()+interval '1 hour');
 request=jsonb_build_object('id',mid,'recipient',b,'bytes',128,'sha256',repeat('0',64),'token',ta);
 perform public.myaow_media('media_prepare',request);
 perform public.myaow_media('media_prepare',request);
 if (select count(*) from myaow_private.media where id=mid)<>1 then raise exception 'Duplicate reservation'; end if;
 begin perform public.myaow_media('media_prepare',request||jsonb_build_object('bytes',129)); raise exception 'Reused id changed bytes'; exception when unique_violation then null; end;
 begin perform public.myaow_media('media_download',jsonb_build_object('id',mid,'token',tb)); raise exception 'Uncommitted download'; exception when no_data_found then null; end;
 begin perform public.myaow_media('media_commit',jsonb_build_object('id',mid,'token',tb)); raise exception 'Foreign commit'; exception when insufficient_privilege then null; end;
 perform public.myaow_media('media_commit',jsonb_build_object('id',mid,'token',ta));
 perform public.myaow_media('media_download',jsonb_build_object('id',mid,'token',tb));
 begin perform public.myaow_media('media_download',jsonb_build_object('id',mid,'token',tc)); raise exception 'Foreign download'; exception when insufficient_privilege then null; end;
 insert into myaow_private.blocks values(b,a);
 begin perform public.myaow_media('media_download',jsonb_build_object('id',mid,'token',tb)); raise exception 'Blocked download'; exception when insufficient_privilege then null; end;
 begin perform public.myaow_media('media_prepare',request||jsonb_build_object('id',gen_random_uuid())); raise exception 'Blocked upload'; exception when insufficient_privilege then null; end;
 delete from myaow_private.blocks where owner=b and target=a;
 insert into myaow_private.groups(id,owner,name) values(gid,a,'Media test');
 insert into myaow_private.group_members values(gid,a,'owner'),(gid,b,'member');
 perform public.myaow_media('media_prepare',jsonb_build_object('id',gm,'groupId',gid,'bytes',128,'sha256',repeat('0',64),'token',ta));
 perform public.myaow_media('media_commit',jsonb_build_object('id',gm,'token',ta));
 perform public.myaow_media('media_download',jsonb_build_object('id',gm,'token',tb));
 insert into myaow_private.group_members values(gid,c,'member');
 begin perform public.myaow_media('media_download',jsonb_build_object('id',gm,'token',tc)); raise exception 'New member read history'; exception when insufficient_privilege then null; end;
 delete from myaow_private.group_members where group_id=gid and member=b;
 begin perform public.myaow_media('media_download',jsonb_build_object('id',gm,'token',tb)); raise exception 'Removed member download'; exception when insufficient_privilege then null; end;
 begin perform public.myaow_media('media_prepare',request||jsonb_build_object('id',gen_random_uuid(),'bytes',10485789)); raise exception 'Oversized reserve'; exception when invalid_parameter_value then null; end;
 begin perform public.myaow_media('media_remove',jsonb_build_object('id',mid,'token',tb)); raise exception 'Foreign delete'; exception when insufficient_privilege then null; end;
 delete from myaow_private.sessions where owner=b;
 begin perform public.myaow_media('media_download',jsonb_build_object('id',mid,'token',tb)); raise exception 'Revoked session'; exception when invalid_authorization_specification then null; end;
 if has_function_privilege('anon','public.myaow_media(text,jsonb)','execute') or has_function_privilege('authenticated','public.myaow_media(text,jsonb)','execute') then raise exception 'Exposed media RPC'; end if;
 if (select public from storage.buckets where id='myaow-ciphertext') then raise exception 'Public bucket'; end if;
end $$;
rollback;
